package com.specdriven.regression.runner;
import static org.assertj.core.api.Assertions.*;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.*;
import java.io.*;import java.nio.file.*;import java.security.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;
class RemoteRunnerServiceTest {
 static final ObjectMapper JSON=new ObjectMapper();@TempDir Path temp;Path binding,bundle,spec,source,out;ObjectNode config;Driver driver;
 static String sha(byte[] b)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(b));}
 @BeforeEach void setup()throws Exception{
  source=Files.createDirectory(temp.resolve("worker-output"));Files.createDirectories(source.resolve("logs"));Files.writeString(source.resolve("logs/run.stdout.log"),"public worker log\n");
  bundle=temp.resolve("bundle.json");Files.writeString(bundle,"{\"schema_version\":\"runner-bundle.v1\",\"classification\":\"derived_execution_snapshot\"}\n");
  spec=temp.resolve("collection.json");var c=JSON.createObjectNode();c.put("schema_version","runner-collection.v1");c.put("run_id","public-run");c.put("correlation_id","public-correlation");c.put("payload_profile","standard");c.put("deadline_ms",30000);c.putNull("canonical_result");var versions=c.putObject("artifact_versions");for(String k:List.of("runner","framework","provider","source","bundle","sut"))versions.put(k,"public-fixture");var file=c.putArray("files").addObject();file.put("path","logs/run.stdout.log");file.put("role","log");file.put("required",true);file.put("bytes",Files.size(source.resolve("logs/run.stdout.log")));file.put("sha256",sha(Files.readAllBytes(source.resolve("logs/run.stdout.log"))));Files.write(spec,JSON.writeValueAsBytes(c));
  config=JSON.createObjectNode();config.put("schema_version","runner-runtime-binding.v1");config.put("binding_id","public-binding");config.put("runtime_type","contract_test");config.put("owner_nonce","public-owner");config.put("run_id","public-run");config.put("correlation_id","public-correlation");config.put("evidence_classification","framework_verification_only");config.put("collection_spec_sha256",sha(Files.readAllBytes(spec)));config.put("bundle_sha256",sha(Files.readAllBytes(bundle)));config.put("expected_sut_revision","sut-public-v1");config.put("observed_sut_revision","sut-public-v1");config.put("readiness_evidence_sha256","1".repeat(64));config.put("runtime_identity","public-contract-fixture");config.put("maximum_run_ms",10000);binding=temp.resolve("runtime.json");out=temp.resolve("controller");driver=new Driver();
 }
 RemoteRunnerService.Result run()throws Exception{Files.write(binding,JSON.writeValueAsBytes(config));return new RemoteRunnerService(driver).execute(binding,sha(Files.readAllBytes(binding)),bundle,spec,out);}
 class Driver implements RemoteRunnerService.Transport {
  final List<String> calls=new ArrayList<>();boolean timeout,foreign,cleanupFail,captureFail,writeFail,ackFail,stopFail,awaitFail;int exit;
  public boolean nativeTransport(){return false;}
  public RemoteRunnerService.Handle launch(JsonNode b,Path manifest){calls.add("launch");return new RemoteRunnerService.Handle("owned-contract-id",foreign?"another-owner":"public-owner","public-run");}
  public RemoteRunnerService.Observation await(RemoteRunnerService.Handle h,long deadline)throws IOException{calls.add("supervise");if(awaitFail)throw new IOException("public supervision failure");return new RemoteRunnerService.Observation(exit,timeout,"public-mock-runtime-v1");}
  public void stopOwned(RemoteRunnerService.Handle h)throws IOException{assertThat(h.ownerNonce()).isEqualTo("public-owner");calls.add("stop-owned-preserve-output");if(stopFail)throw new IOException("public stop failure");}
  public Path availableEvidence(RemoteRunnerService.Handle h,JsonNode c,long deadline)throws IOException{calls.add("capture");if(captureFail)throw new IOException("public capture failure");if(writeFail)Files.createDirectory(out.resolve("collected"));return source;}
  public void acknowledgeSaved(RemoteRunnerService.Handle h,String hash)throws IOException{assertThat(hash).matches("[a-f0-9]{64}");assertThat(Files.isRegularFile(out.resolve("controller-SAVE.json"))).isTrue();assertThat(Files.isRegularFile(out.resolve("collected/SAVE.complete"))).isTrue();calls.add("ack-saved");if(ackFail)throw new IOException("public ack failure");}
  public void cleanupOwned(RemoteRunnerService.Handle h)throws IOException{assertThat(h.runtimeId()).isEqualTo("owned-contract-id");assertThat(calls).contains("ack-saved");assertThat(Files.isRegularFile(out.resolve("collected/collection.json"))).isTrue();calls.add("cleanup-owned");if(cleanupFail)throw new IOException("public cleanup failure");}
 }
 @Test void durableSavePrecedesAckAndOwnedCleanup()throws Exception{var r=run();assertThat(driver.calls).containsExactly("launch","supervise","capture","ack-saved","cleanup-owned");assertThat(r.facts().path("cleanup").asText()).isEqualTo("CLEAN");assertThat(r.facts().path("runtime_acceptance").asText()).isEqualTo("CONTRACT_ONLY_NOT_NATIVE");assertThat(r.facts().path("framework_verdict").asText()).isEqualTo("UNKNOWN");}
 @Test void nonzeroRunnerExitIsSeparateFromProductVerdict()throws Exception{driver.exit=7;var r=run();assertThat(r.facts().path("runner_exit_code").asInt()).isEqualTo(7);assertThat(r.facts().path("framework_verdict").asText()).isEqualTo("UNKNOWN");assertThat(r.facts().path("collection").asText()).isEqualTo("COMPLETE");}
 @Test void timeoutCollectsAvailablePartialBeforeRetainingUnretrievedWorkspace()throws Exception{driver.timeout=true;Files.delete(source.resolve("logs/run.stdout.log"));var r=run();assertThat(driver.calls).containsExactly("launch","supervise","stop-owned-preserve-output","capture");assertThat(r.facts().path("execution").asText()).isEqualTo("TIMED_OUT");assertThat(r.facts().path("collection").asText()).isEqualTo("PARTIAL");assertThat(r.facts().path("cleanup").asText()).contains("NOT_ATTEMPTED");}
 @Test void invalidOrTamperedEvidenceCannotAcknowledgeOrCleanup()throws Exception{Files.writeString(source.resolve("logs/run.stdout.log"),"changed");var r=run();assertThat(r.facts().path("collection").asText()).isEqualTo("INVALID");assertThat(driver.calls).doesNotContain("ack-saved","cleanup-owned");}
 @Test void captureFailureKeepsCollectionAndPublicationFailureExplicit()throws Exception{driver.captureFail=true;var r=run();assertThat(r.facts().path("publication").asText()).isEqualTo("FAILED");assertThat(driver.calls).doesNotContain("cleanup-owned");}
 @Test void collectionWriteFailureCannotDeleteOwnedWorkspace()throws Exception{driver.writeFail=true;var r=run();assertThat(r.facts().path("publication").asText()).isEqualTo("FAILED");assertThat(driver.calls).doesNotContain("ack-saved","cleanup-owned");}
 @Test void cleanupFailureRetainsSavedEvidenceAndFailureGap()throws Exception{driver.cleanupFail=true;var r=run();assertThat(r.facts().path("cleanup").asText()).isEqualTo("FAILED");assertThat(Files.isRegularFile(out.resolve("collected/SAVE.complete"))).isTrue();}
 @Test void foreignOwnerNeverGetsSupervisedOrCleaned()throws Exception{driver.foreign=true;var r=run();assertThat(driver.calls).containsExactly("launch");assertThat(r.facts().path("cleanup").asText()).contains("UNOWNED");}
 @Test void deployedVersionMismatchBlocksBeforeAnyTransportCall()throws Exception{config.put("observed_sut_revision","other");assertThatThrownBy(this::run).hasMessageContaining("SUT_DEPLOYED_REVISION_MISMATCH");assertThat(driver.calls).isEmpty();}
 @Test void nativeLabelCannotPromoteMockOrLocalProcessToRemotePass()throws Exception{config.put("runtime_type","kubernetes");assertThatThrownBy(this::run).hasMessageContaining("NATIVE_RUNTIME_BINDING_UNBOUND");assertThat(driver.calls).isEmpty();}
 @Test void timeoutStopFailureStillCollectsExactlyOnceAndRetains()throws Exception{driver.timeout=true;driver.stopFail=true;var r=run();assertThat(driver.calls).containsExactly("launch","supervise","stop-owned-preserve-output","capture");assertThat(r.facts().path("execution").asText()).isEqualTo("TIMED_OUT");assertThat(r.facts().path("stop_status").asText()).isEqualTo("FAILED");assertThat(r.facts().path("publication").asText()).isEqualTo("SAVED");assertThat(r.facts().path("cleanup").asText()).contains("NOT_ATTEMPTED");}
 @Test void supervisionAndStopFailureCannotBypassAvailableEvidence()throws Exception{driver.awaitFail=true;driver.stopFail=true;var r=run();assertThat(driver.calls).containsExactly("launch","supervise","stop-owned-preserve-output","capture");assertThat(r.facts().path("execution").asText()).isEqualTo("SUPERVISION_FAILED");assertThat(r.facts().path("stop_status").asText()).isEqualTo("FAILED");assertThat(Files.exists(out.resolve("collected/collection.json"))).isTrue();}
 @Test void acknowledgementFailureNeverTriggersCleanup()throws Exception{driver.ackFail=true;var r=run();assertThat(driver.calls).doesNotContain("cleanup-owned");assertThat(Files.isRegularFile(out.resolve("collected/SAVE.complete"))).isTrue();}
 @Test void completionMarkerFailureNeverAcknowledgesOrCleansOwnedWorkspace()throws Exception{Files.write(binding,JSON.writeValueAsBytes(config));var port=new RunnerDurabilityTest.Port(out.resolve("collected"));port.failFile="SAVE.complete";var result=new RemoteRunnerService(driver,port).execute(binding,sha(Files.readAllBytes(binding)),bundle,spec,out);assertThat(result.facts().path("publication").asText()).isEqualTo("FAILED");assertThat(result.facts().path("cleanup").asText()).contains("NOT_ATTEMPTED");assertThat(driver.calls).containsExactly("launch","supervise","capture");assertThat(Files.exists(out.resolve("collected/SAVE.complete"))).isFalse();assertThat(Files.readString(source.resolve("logs/run.stdout.log"))).isEqualTo("public worker log\n");}
}
